<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);$view=file_get_contents($root.'/app/views/paciente/entrevista.php');$assert=static function(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);};
$assert(str_contains($view,'patient-interview-voice.js'),'The interview must reuse one voice controller asset');
$assert(str_contains($view,"dirname(__DIR__, 3) . '/public/'"),'The interview must resolve asset versioning from the project public directory');
$assert(str_contains($view,'data-voice-repeat') && str_contains($view,'data-voice-stop'),'Voice guide must expose repeat and stop controls');
$assert(str_contains($view,'repeatOrUnlockVoice') && str_contains($view,'voiceController.activate(event, null, {userGesture:true})')
    && str_contains($view,'voiceController.speakEvent(event, {force:true, userGesture:true})'),'Repeat control must safely unlock blocked autoplay or replay the current question through the existing controller');
$assert(!str_contains($view,'data-voice-start') && !str_contains($view,'data-voice-pause') && !str_contains($view,'data-voice-resume') && !str_contains($view,'data-voice-mute'),'Voice panel must not expose separate start, pause, or mute controls');
$assert(str_contains($view,'data-voice-rate'),'Voice speed control missing');
$assert(str_contains($view,'aria-label="Repetir pregunta"') && str_contains($view,'aria-label="Detener narración"'),'Icon-only voice actions must have accessible names');
$assert(str_contains($view,'class="visually-hidden" data-voice-status aria-live="polite"'),'Voice status must remain announced without taking panel space');
$assert(str_contains($view,"event.type === 'RESUME'") && str_contains($view,'voiceController.handleEvent(question)'),'Resume must narrate only the active question');
$assert(str_contains($view,"['SAVING', 'SUCCESS', 'ERROR', 'SESSION_EXPIRED']"),'Technical coordinator events must not be narrated automatically');
$assert(str_contains($view,'voiceController.handleEvent(event)'),'Question narration must use the single active event');
$assert(str_contains($view,'handleVoiceEvent'),'Coordinator voice events must reach the voice controller');
$assert(str_contains($view,'visibilitychange'),'Voice must stop when the page is hidden');
$assert(str_contains($view,'patient-interview-question patient-interview-active-question'),'M02 must reuse the single-question visual card');
$assert(!str_contains($view,'data-m02-defer') && !str_contains($view,'Responder después'),'M02 must not expose a defer action');
$assert(!str_contains($view,'data-m02-quick') && str_contains($view,'No, guardar y continuar'),'M02 must accept affirmative text while preserving the authorized negative action');
$assert(!str_contains($view,'recognition.processLocally = true'),'The working browser recognition must not be forced into processLocally mode.');
$assert(str_contains($view,'new recognitionConstructor()'),'Local speech recognition must be detected on an instance, not only on the prototype.');
$assert(str_contains($view,'recognitionConstructor.available'),'Voice language availability is not checked when exposed by the browser.');
$assert(str_contains($view,"state === 'available'"),'Voice availability status must be recorded when the browser exposes it.');
$assert(str_contains($view,'🎙 No disponible'),'Unavailable microphone state missing');
$assert(str_contains($view,"document.createElement('button')"),'Unavailable microphone must remain an accessible explanatory control.');
$assert(str_contains($view,"indicator.addEventListener('click'"),'Unavailable microphone must explain the local-only limitation when activated.');
$assert(str_contains($view,'speechSynthesis'),'Local TTS missing');
$assert(str_contains($view,'activateAutomatically'),'Voice guide must activate automatically when the browser permits it');
$assert(str_contains($view,'AUDIO_BLOCKED'),'Autoplay blocking must remain visible and fail safe');
$assert(str_contains($view,'sessionStorage'),'Mute preference must remain scoped to the interview session');
$assert(str_contains($view,'activateAutomatically(question)'),'Automatic narration must send the active question directly to TTS');
$assert(str_contains($view,'const question = startup.question;') && str_contains($view,'voiceController.activateAutomatically(question);'),'Automatic audio must use the current server-resolved question event');
$assert(str_contains($view,'return {question};'),'Startup resolver must return only the active question event');
$assert(!str_contains($view,"voiceEvent('WELCOME')") && !str_contains($view,"voiceEvent('FIRST_START'") && !str_contains($view,"voiceEvent('RESUME', snapshot.currentTarget") && !str_contains($view,'Continuemos con tu entrevista'),'Startup must not build or speak generic narration prefixes');
$assert(!str_contains($view,'hasPersistedInterviewState'),'Client-side persisted-state scan must not determine interview start');
$assert(str_contains($view,'nativeSttEnabled') && str_contains($view,'startRecognition'),'STT must remain manual and separately guarded');
$assert(str_contains($view,'stopAssistantVoice'),'TTS stop transition missing');
$assert(!str_contains($view,'Comencemos con la siguiente pregunta pendiente'),'Obsolete smoking introduction remains');
echo 'Voice/navigation contract: PASS (' . substr_count(file_get_contents(__FILE__), '$assert(') . " assertions; no database writes)\n";
